INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',557,'{"_type":"chat:Message","id":"8641420749:1273","threadId":"telegram:8641420749","text":"Avant 0/10, pendant j’ai eu un passage à 2/10 mais ca venait et ca repartait. Sur le plat entre Duingt, Doussard et Talloires j’etais a 140bpm de FC en appuyant bien sur les pedales et j’avais pas mal. J’ai fini a 0-1/10, la je suis a 1/10. Mais rien de méchant. Un peu de glace ce soir a la limite.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Avant 0/10, pendant j’ai eu un passage à 2/10 mais ca venait et ca repartait. Sur le plat entre Duingt, Doussard et Talloires j’etais a 140bpm de FC en appuyant bien sur les pedales et j’avais pas mal. J’ai fini a 0-1/10, la je suis a 1/10. Mais rien de méchant. Un peu de glace ce soir a la limite.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":300,"offset":299}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":300,"offset":299}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":300,"offset":299}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-16T12:37:22.000Z","edited":false},"attachments":[],"isMention":false}',1787488642009);
